def balanced(s: str) -> bool:
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}
    opening_brackets = set(mapping.values())
    closing_brackets = set(mapping.keys())

    for char in s:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack or stack.pop() != mapping[char]:
                return False
    return not stack
```

