def spiral(m: list[list[int]]) -> list[int]:
    if not m or not m[0]:
        return []

    rows, cols = len(m), len(m[0])
    result = []
    top, bottom, left, right = 0, rows - 1, 0, cols - 1

    while top <= bottom and left <= right:
        # Traverse right (top row)
        for i in range(left, right + 1):
            result.append(m[top][i])
        top += 1

        if top > bottom:
            break

        # Traverse down (right column)
        for i in range(top, bottom + 1):
            result.append(m[i][right])
        right -= 1

        if left > right:
            break

        # Traverse left (bottom row)
        for i in range(right, left - 1, -1):
            result.append(m[bottom][i])
        bottom -= 1

        if top > bottom:
            break

        # Traverse up (left column)
        for i in range(bottom, top - 1, -1):
            result.append(m[i][left])
        left += 1

    return result
